WitnessNumberIsTwo.everywhere:
{ℓd ℓx ℓ : Level} {D : Type ℓd} {X : Type ℓx}
(law : D → X → Type ℓ) (d : D) →
((x : X) → law d x) → (xs : List X) → AllHold law d xs

WitnessNumberIsTwo.refutes→absent:
{ℓd ℓx ℓ : Level} {D : Type ℓd} {X : Type ℓx}
(law : D → X → Type ℓ) (d : List X) →
Refutes law d → ¬ Σ-syntax D (λ x → (xs : X) → law x xs)

WitnessNumberIsTwo.factorLaw:
{ℓx = ℓd : Level} {ℓy = ℓx : Level} {ℓt = ℓ : Level}
{X = D : Type ℓd} {Y = X : Type ℓx} {T = law : Type ℓ}
(d : D → X) →
(D → law) → (Image d → law) → D → Type ℓ
